#!/usr/bin/env bash
# Session 6 — controller product installer: hermetic tests for the pure-ish
# pieces of installer-lib.sh (no root, no systemd, no network):
#   1. the STAGED finalize script (generated by ssh_stage_finalize) actually
#      runs: anchored port keep, password-auth lines, SSH_CONNECTION guard;
#   2. fw_remove_port only removes ownership-tagged rules (ufw + iptables).
# Everything runs against stub binaries on a restricted PATH.
set -u
ROOT="$(cd "$(dirname "$0")/.." && pwd)"
T="$(mktemp -d)"
trap 'rm -rf "$T"' EXIT
mkdir -p "$T/stub" "$T/lib" "$T/out"
fail=0
chk() { [[ "$2" == "$3" ]] || { echo "FAIL $1: got '$2' want '$3'"; fail=1; }; }

# --- sandbox: stub systemctl/ss/sshd/ufw/iptables/ssh-keygen on PATH ---------
cat > "$T/stub/systemctl" <<'EOF'
#!/bin/sh
case "$1 $2 $3" in
  "is-active --quiet ssh.socket") exit 1 ;;
  *) exit 0 ;;
esac
EOF
cat > "$T/stub/ss" <<'EOF'
#!/bin/sh
# reports the new port listening on loopback
echo "LISTEN 0 128 0.0.0.0:${FAKE_LISTEN_PORT:-2222} 0.0.0.0:*"
EOF
cat > "$T/stub/sshd" <<'EOF'
#!/bin/sh
exit 0   # sshd -t always validates in the sandbox
EOF
cat > "$T/stub/ufw" <<'EOF'
#!/bin/sh
case "$1" in
  status) echo "Status: active"; echo "2222/tcp                     ALLOW       # quantum:controller:ssh-alt" ;;
  *) echo "$@" >> "$UFLOG"; exit 0 ;;
esac
EOF
cat > "$T/stub/iptables" <<'EOF'
#!/bin/sh
echo "$@" >> "$IPTLOG"
exit 0
EOF
chmod +x "$T/stub/"*
export PATH="$T/stub:$PATH"

# --- load the lib with install-side globals sandboxed ------------------------
# NOTE: set the sandbox paths AFTER sourcing — the lib re-assigns its own
# constants on source.
Q_BACKUP_DIR="$T/out/backups"
# shellcheck disable=SC2034
UFLOG="$T/out/ufw.log"; IPTLOG="$T/out/ipt.log"
export UFLOG IPTLOG FAKE_LISTEN_PORT=2222
# shellcheck disable=SC1090
source "$ROOT/installer-lib.sh"
Q_SSH_DROPIN="$T/out/60-quantum-ssh.conf"
Q_SSH_FINALIZE_BIN="$T/out/quantum-ssh-finalize"
mkdir -p "$T/out" "$Q_BACKUP_DIR"

# --- 1. ssh_stage_finalize: generated script behavior ------------------------
ssh_stage_finalize "2222"
[[ -x "$Q_SSH_FINALIZE_BIN" ]] || { echo "FAIL: finalize binary not staged"; exit 1; }
printf 'Port 22\nPort 2222\nPort 22221\nPort 2097\n' > "$Q_SSH_DROPIN"

# 1a. guard: an SSH session on the WRONG port must be refused (exit 3)
out="$(SSH_CONNECTION="203.0.113.9 51000 198.51.100.7 22" "$Q_SSH_FINALIZE_BIN" --yes 2>&1)"
rc=$?
chk "guard-wrong-port-rc" "$rc" "3"
case "$out" in *"arrived on port 22"*) : ;; *) echo "FAIL guard message: $out"; fail=1 ;; esac

# 1b. guard: an SSH session on the NEW port is allowed; anchored keep runs
FAKE_LISTEN_PORT=2222 SSH_CONNECTION="203.0.113.9 51000 198.51.100.7 2222" \
    "$Q_SSH_FINALIZE_BIN" --yes >/dev/null 2>&1
chk "guard-right-port-rc" "$?" "0"
grep -q '^Port 2222$' "$Q_SSH_DROPIN" && r1=ok || r1=missing
chk "keep-new-port" "$r1" "ok"
grep -q '^Port 22$' "$Q_SSH_DROPIN" && r2=BAD || r2=dropped
chk "drop-old-port" "$r2" "dropped"
grep -q '^Port 22221$' "$Q_SSH_DROPIN" && r3=BAD || r3=dropped
chk "anchored-22221-dropped" "$r3" "dropped"
grep -q '^Port 2097$' "$Q_SSH_DROPIN" && r4=BAD || r4=dropped
chk "drop-other-quantum-port" "$r4" "dropped"
grep -q '^PasswordAuthentication no$' "$Q_SSH_DROPIN" && r5=ok || r5=missing
chk "password-auth-off" "$r5" "ok"

# 1c. console session (no SSH_CONNECTION) is allowed on a fresh tombstone
printf 'Port 22\nPort 2222\n' > "$Q_SSH_DROPIN"
"$Q_SSH_FINALIZE_BIN" --yes >/dev/null 2>&1
chk "guard-console-allowed" "$?" "0"

# 1d. pubkey-only bootstrap (no new port): guard must NOT demand port 22
ssh_stage_finalize ""
FAKE_LISTEN_PORT=22 SSH_CONNECTION="203.0.113.9 51000 198.51.100.7 2222" \
    "$Q_SSH_FINALIZE_BIN" --yes >/dev/null 2>&1
chk "guard-no-portchange-allowed" "$?" "0"

# --- 2. fw_remove_port: only ownership-tagged rules --------------------------
: > "$UFLOG"
fw_remove_port controller "ssh-alt" 2222 tcp
grep -q "delete allow 2222/tcp" "$UFLOG" && r6=ok || r6=no
chk "ufw-delete-called" "$r6" "ok"

# iptables backend: remove only when -C confirms the TAGGED rule exists
: > "$IPTLOG"
fw_has_rule() { return 1; }   # force the iptables branch (no ufw active)
q_have() { case "$1" in ufw) return 1 ;; *) return 0 ;; esac; }
fw_remove_port controller "ssh-alt" 2222 tcp
grep -q "\-C INPUT -p tcp --dport 2222 -m comment --comment quantum:controller:ssh-alt -j ACCEPT" "$IPTLOG" && r7=ok || r7=no
chk "iptables-check-tagged" "$r7" "ok"
grep -q "\-D INPUT -p tcp --dport 2222 -m comment --comment quantum:controller:ssh-alt -j ACCEPT" "$IPTLOG" && r8=ok || r8=no
chk "iptables-delete-tagged" "$r8" "ok"

# untagged rule must NOT be removed: -C fails (rule absent) -> no -D
: > "$IPTLOG"
cat > "$T/stub/iptables" <<'EOF'
#!/bin/sh
echo "$@" >> "$IPTLOG"
[ "$1" = "-C" ] && exit 1
exit 0
EOF
fw_remove_port controller "other" 9999 tcp
grep -q " -D INPUT" "$IPTLOG" && r9=BAD || r9=skipped
chk "iptables-no-delete-without-match" "$r9" "skipped"

# --- 3b. ssh_verify_listening retry (SSH_LISTEN_TRIES is a real knob) --------
mkdir -p "$T/stub2"
export SSCOUNT="$T/out/sscount"; echo 0 > "$SSCOUNT"
cat > "$T/stub2/ss" <<'EOF'
#!/bin/sh
N=$(cat "$SSCOUNT" 2>/dev/null || echo 0)
N=$((N + 1)); echo "$N" > "$SSCOUNT"
# the port appears only from the 3rd poll on (async rebind simulation)
[ "$N" -ge 3 ] && echo "LISTEN 0 128 0.0.0.0:2222 0.0.0.0:*"
exit 0
EOF
chmod +x "$T/stub2/ss"
PATH="$T/stub2:$PATH" SSH_LISTEN_TRIES=5 SSH_LISTEN_SLEEP=0 ssh_verify_listening 2222
chk "retry-eventual-listen" "$?" "0"
echo 0 > "$SSCOUNT"
PATH="$T/stub2:$PATH" SSH_LISTEN_TRIES=1 SSH_LISTEN_SLEEP=0 ssh_verify_listening 2222
chk "retry-no-tries-fails-fast" "$?" "1"

# --- 3. installer-lib syntax + PS1 label rule presence -----------------------
bash -n "$ROOT/installer-lib.sh" || { echo "FAIL: installer-lib syntax"; fail=1; }
grep -q "if (\$Label -notmatch '^\[A-Za-z0-9\]\[A-Za-z0-9._-\]{0,63}\$')" "$ROOT/tools/QuantumSshKey.ps1" \
    && r10=ok || r10=missing
chk "ps1-label-rule" "$r10" "ok"
grep -q 'ToBase64String' "$ROOT/tools/QuantumSshKey.ps1" && r11=ok || r11=missing
chk "ps1-base64-transport" "$r11" "ok"
grep -q "LIB_SHA256" "$ROOT/install-agent.sh" && r12=ok || r12=missing
chk "agent-lib-pinned" "$r12" "ok"
grep -q "raw.githubusercontent.com/Dark-modem/quantum/main/" "$ROOT/install-agent.sh" \
    && r13=BAD || r13=removed
chk "agent-unpinned-main-gone" "$r13" "removed"

if [[ $fail -eq 0 ]]; then echo "PASS test_controller_product"; else echo "FAIL test_controller_product"; exit 1; fi
